import React, { useState, useEffect } from 'react';

function NavBar(props) {
  const [isTop, setIsTop] = useState(!props.fixed);
  const [showMenu, setShowMenu] = useState(false);
  const [activeDropdown, setActiveDropdown] = useState(null);
  const [dropdownTimeout, setDropdownTimeout] = useState(null);

  const handleScroll = () => {
    const scrollPosition = window.scrollY;
    const isTop = scrollPosition === 0;
    setIsTop(isTop && !props.fixed);
  };

  useEffect(() => {
    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const handleMouseEnter = (dropdown) => {
    if (dropdownTimeout) {
      clearTimeout(dropdownTimeout);
      setDropdownTimeout(null);
    }
    setActiveDropdown(dropdown);
  };

  const handleMouseLeave = () => {
    const timeout = setTimeout(() => {
      setActiveDropdown(null);
    }, 150); // Small delay to allow clicking
    setDropdownTimeout(timeout);
  };

  const handleLinkClick = () => {
    setActiveDropdown(null);
    if (dropdownTimeout) {
      clearTimeout(dropdownTimeout);
      setDropdownTimeout(null);
    }
  };

  const navbarClass = "fixed w-full top-0 z-1000 text-white backdrop-blur-md";
  const navbarStyle = {
    backgroundColor: `rgba(15, 23, 42, ${isTop ? 0.8 : 0.95})`,
    borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
  };

  return (
    <nav className={navbarClass} style={navbarStyle}>
      <div className="max-w-6xl mx-auto px-4">
        <div className="flex items-center justify-between h-16">
          
          {/* Logo */}
          <div className="flex-shrink-0">
            <a href="/" className="flex items-center">
              <img src="/logo_name.png" alt="7DT Logo" className="h-8" />
            </a>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden md:block">
            <div className="flex items-center space-x-8">
              <a href="/" className="text-white hover:text-primary-300 transition-colors px-3 py-2 rounded-md text-sm font-medium">
                Home
              </a>
              
              {/* About Dropdown */}
              <div className="relative" onMouseEnter={() => handleMouseEnter('about')} onMouseLeave={handleMouseLeave}>
                <button className="text-white hover:text-primary-300 transition-colors px-3 py-2 rounded-md text-sm font-medium">
                  About
                </button>
                {activeDropdown === 'about' && (
                  <div className="absolute top-full left-0 mt-1 w-48 bg-white rounded-md shadow-lg py-1 z-50">
                    <a href="/about/intro" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>What is 7DS</a>
                    <a href="/about/team" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Team</a>
                    <a href="/about/funding" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Funding</a>
                  </div>
                )}
              </div>

              {/* Science Dropdown */}
              <div className="relative" onMouseEnter={() => handleMouseEnter('science')} onMouseLeave={handleMouseLeave}>
                <button className="text-white hover:text-primary-300 transition-colors px-3 py-2 rounded-md text-sm font-medium">
                  Science
                </button>
                {activeDropdown === 'science' && (
                  <div className="absolute top-full left-0 mt-1 w-48 bg-white rounded-md shadow-lg py-1 z-50">
                    <a href="/science/overview" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Overview</a>
                    <a href="/science/sci" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Multi-messenger Astronomy</a>
                    <a href="/science/sci" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Galaxy Formation</a>
                    <a href="/science/sci" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Cosmology</a>
                    <a href="/science/sci" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Active Galactic Nuclei</a>
                    <a href="/science/sci" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Galactic Science</a>
                    <a href="/science/sci" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Solar System Objects</a>
                    <a href="/science/sci" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Transients</a>
                  </div>
                )}
              </div>

              {/* Survey Dropdown */}
              <div className="relative" onMouseEnter={() => handleMouseEnter('survey')} onMouseLeave={handleMouseLeave}>
                <button className="text-white hover:text-primary-300 transition-colors px-3 py-2 rounded-md text-sm font-medium">
                  Survey
                </button>
                {activeDropdown === 'survey' && (
                  <div className="absolute top-full left-0 mt-1 w-48 bg-white rounded-md shadow-lg py-1 z-50">
                    <a href="/survey/overview" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Overview</a>
                    <a href="/survey/design" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Design</a>
                    <a href="/survey/status" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Status</a>
                  </div>
                )}
              </div>

              {/* Telescope Dropdown */}
              <div className="relative" onMouseEnter={() => handleMouseEnter('telescope')} onMouseLeave={handleMouseLeave}>
                <button className="text-white hover:text-primary-300 transition-colors px-3 py-2 rounded-md text-sm font-medium">
                  Telescope
                </button>
                {activeDropdown === 'telescope' && (
                  <div className="absolute top-full left-0 mt-1 w-48 bg-white rounded-md shadow-lg py-1 z-50">
                    <a href="/telescope/overview" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Overview</a>
                    <a href="/telescope/location" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Location</a>
                    <a href="/telescope/instrument" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Instrument</a>
                    <a href="/telescope/computer" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Computational Resources</a>
                    <a href="/telescope/mode" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Observing Mode</a>
                  </div>
                )}
              </div>

              {/* Data Dropdown */}
              <div className="relative" onMouseEnter={() => handleMouseEnter('data')} onMouseLeave={handleMouseLeave}>
                <button className="text-white hover:text-primary-300 transition-colors px-3 py-2 rounded-md text-sm font-medium">
                  Data
                </button>
                {activeDropdown === 'data' && (
                  <div className="absolute top-full left-0 mt-1 w-48 bg-white rounded-md shadow-lg py-1 z-50">
                    <a href="/data/overview" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Overview</a>
                    <a href="/data/data" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Data</a>
                    <a href="/data/software" className="block px-4 py-2 text-sm text-gray-700 hover:bg-gray-100" onClick={handleLinkClick}>Software</a>
                  </div>
                )}
              </div>

              <a href="/publication" className="text-white hover:text-primary-300 transition-colors px-3 py-2 rounded-md text-sm font-medium">
                Publications
              </a>
              <a href="/news" className="text-white hover:text-primary-300 transition-colors px-3 py-2 rounded-md text-sm font-medium">
                News
              </a>
            </div>
          </div>

          {/* Mobile menu button */}
          <div className="md:hidden">
            <button 
              onClick={() => setShowMenu(!showMenu)} 
              className="inline-flex items-center justify-center p-2 rounded-md text-gray-300 hover:text-white hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-white transition-colors"
              aria-expanded={showMenu}
              aria-label="Toggle navigation menu"
            >
              <span className="sr-only">Open main menu</span>
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
          </div>
        </div>

        {/* Mobile Navigation */}
        {showMenu && (
          <div className="md:hidden">
            <div className="px-2 pt-2 pb-3 space-y-1 bg-gray-800 rounded-md mt-2">
              <a href="/" className="text-white hover:text-primary-300 block px-3 py-2 rounded-md text-base font-medium">
                Home
              </a>
              <a href="/about/intro" className="text-white hover:text-primary-300 block px-3 py-2 rounded-md text-base font-medium">
                About
              </a>
              <a href="/science/overview" className="text-white hover:text-primary-300 block px-3 py-2 rounded-md text-base font-medium">
                Science
              </a>
              <a href="/survey/overview" className="text-white hover:text-primary-300 block px-3 py-2 rounded-md text-base font-medium">
                Survey
              </a>
              <a href="/telescope/overview" className="text-white hover:text-primary-300 block px-3 py-2 rounded-md text-base font-medium">
                Telescope
              </a>
              <a href="/data/overview" className="text-white hover:text-primary-300 block px-3 py-2 rounded-md text-base font-medium">
                Data
              </a>
              <a href="/publication" className="text-white hover:text-primary-300 block px-3 py-2 rounded-md text-base font-medium">
                Publications
              </a>
              <a href="/news" className="text-white hover:text-primary-300 block px-3 py-2 rounded-md text-base font-medium">
                News
              </a>
            </div>
          </div>
        )}
      </div>
    </nav>
  );
}

export default NavBar;


    

