import React, { useEffect, useState, useRef } from 'react';
import news from './content/news.json'
import { mainText1, mainText2, mainText3, mainText4 } from './content/text'
import FooterBar from './footer'

const MainPage = () => {
  const [currentSection, setCurrentSection] = useState(0);
  const [sections, setSections] = useState<Element[]>([]);
  const [showScrollToTop, setShowScrollToTop] = useState(false);
  const [animateStats, setAnimateStats] = useState(false);
  const [animateDimensions, setAnimateDimensions] = useState(false);
  const [statsAnimated, setStatsAnimated] = useState(false);
  const [dimensionsAnimated, setDimensionsAnimated] = useState(false);
  const fullpageRef = useRef<HTMLDivElement>(null);

  // Fullpage functionality
  useEffect(() => {
    const fullpageSections = document.querySelectorAll('.fullpage-section');
    const fullpageWrapper = document.querySelector('.fullpage-wrapper') as HTMLElement;
    setSections(Array.from(fullpageSections));

    // Add body and html classes to prevent body scroll
    document.body.classList.add('fullpage-active');
    document.documentElement.classList.add('fullpage-active');

    const handleScroll = () => {
      if (!fullpageWrapper) return;
      
      const scrollY = fullpageWrapper.scrollTop;
      const windowHeight = fullpageWrapper.clientHeight;
      const currentSectionIndex = Math.round(scrollY / windowHeight);
      setCurrentSection(currentSectionIndex);
      
      // Debug logging
      console.log('Current section:', currentSectionIndex, 'Stats animated:', statsAnimated, 'Dimensions animated:', dimensionsAnimated);

      // Update progress bar
      const scrollPercent = (scrollY / (fullpageWrapper.scrollHeight - windowHeight)) * 100;
      const progressBar = document.querySelector('.fullpage-progress') as HTMLElement;
      if (progressBar) {
        progressBar.style.width = `${scrollPercent}%`;
      }

      // Update active section
      fullpageSections.forEach((section, index) => {
        if (index === currentSectionIndex) {
          section.classList.add('active');
        } else {
          section.classList.remove('active');
        }
      });

      // Trigger animations based on current section
      if (currentSectionIndex === 2 && !statsAnimated) { // Science section (index 2)
        setAnimateStats(true);
        setStatsAnimated(true);
      }
      
      if (currentSectionIndex === 3 && !dimensionsAnimated) { // Survey section (index 3)
        setAnimateDimensions(true);
        setDimensionsAnimated(true);
      }
      
      // Reset animation flags when leaving sections
      if (currentSectionIndex !== 2) {
        setStatsAnimated(false);
      }
      
      if (currentSectionIndex !== 3) {
        setDimensionsAnimated(false);
      }

      setShowScrollToTop(scrollY > 300);
    };

    if (fullpageWrapper) {
      fullpageWrapper.addEventListener('scroll', handleScroll);
      return () => {
        fullpageWrapper.removeEventListener('scroll', handleScroll);
        document.body.classList.remove('fullpage-active');
        document.documentElement.classList.remove('fullpage-active');
      };
    }
  }, []);

  // Handle animation completion
  useEffect(() => {
    if (animateStats) {
      const timer = setTimeout(() => {
        setAnimateStats(false);
      }, 2000); // Reset after animation completes
      return () => clearTimeout(timer);
    }
  }, [animateStats]);

  useEffect(() => {
    if (animateDimensions) {
      const timer = setTimeout(() => {
        setAnimateDimensions(false);
      }, 2000); // Reset after animation completes
      return () => clearTimeout(timer);
    }
  }, [animateDimensions]);

  const scrollToSection = (sectionIndex: number) => {
    const targetSection = sections[sectionIndex];
    if (targetSection) {
      targetSection.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const scrollToNext = () => {
    const nextSection = currentSection + 1;
    if (nextSection < sections.length) {
      scrollToSection(nextSection);
    }
  };

  const scrollToPrev = () => {
    const prevSection = currentSection - 1;
    if (prevSection >= 0) {
      scrollToSection(prevSection);
    }
  };

  // Keyboard navigation
  useEffect(() => {
    const handleKeyPress = (e: KeyboardEvent) => {
      switch (e.key) {
        case 'ArrowDown':
        case 'PageDown':
          e.preventDefault();
          scrollToNext();
          break;
        case 'ArrowUp':
        case 'PageUp':
          e.preventDefault();
          scrollToPrev();
          break;
        case 'Home':
          e.preventDefault();
          scrollToSection(0);
          break;
        case 'End':
          e.preventDefault();
          scrollToSection(sections.length - 1);
          break;
      }
    };

    window.addEventListener('keydown', handleKeyPress);
    return () => window.removeEventListener('keydown', handleKeyPress);
  }, [currentSection, sections]);

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  return (
    <div className="fullpage-container" ref={fullpageRef}>
      {/* Fullpage Progress Bar */}
      <div className="fullpage-progress"></div>
      
      {/* Fullpage Navigation Dots */}
      <div className="fullpage-nav">
        {[0, 1, 2, 3, 4, 5, 6].map((index) => (
          <button
            key={index}
            className={`fullpage-dot ${currentSection === index ? 'active' : ''}`}
            onClick={() => scrollToSection(index)}
            aria-label={`Go to section ${index + 1}`}
          />
        ))}
      </div>

      {/* Fullpage Navigation Arrows */}
      <button 
        className="fullpage-arrow up"
        onClick={scrollToPrev}
        aria-label="Previous section"
        style={{ display: currentSection === 0 ? 'none' : 'flex' }}
      >
        <svg viewBox="0 0 24 24">
          <path d="M7.41 15.41L12 10.83l4.59 4.58L18 14l-6-6-6 6z"/>
        </svg>
      </button>
      
      <button 
        className="fullpage-arrow down"
        onClick={scrollToNext}
        aria-label="Next section"
        style={{ display: currentSection === 6 ? 'none' : 'flex' }}
      >
        <svg viewBox="0 0 24 24">
          <path d="M7.41 8.59L12 13.17l4.59-4.58L18 10l-6 6-6-6z"/>
        </svg>
      </button>

      {/* Scroll to Top Button */}
      <button 
        className={`scroll-to-top ${showScrollToTop ? 'visible' : ''}`}
        onClick={scrollToTop}
        aria-label="Scroll to top"
      >
        ↑
      </button>

      {/* Fullpage Wrapper */}
      <div className="fullpage-wrapper">
        {/* Hero Section */}
        <div className="fullpage-section fullpage-hero" style={{ 
          backgroundImage: "linear-gradient(rgba(214, 217, 225, 0.1), rgba(30, 41, 59, 0.1)), url('./img/main.jpg')",
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundRepeat: "no-repeat"
        }}>
          <div className="container">
            <h1>7-Dimensional Telescope</h1>
            <p>Exploring the Universe in Seven Dimensions</p>
          </div>
        </div>

        {/* Introduction Section - Split Layout with Image */}
        <div className="fullpage-section fullpage-content" style={{ 
          backgroundColor: "white"
        }}>
          <div className="container h-full flex items-center">
            <div className="grid grid-cols-2 gap-16 items-center w-full h-full">
              <div className="flex flex-col justify-center h-full">
                <h2 className="text-5xl font-bold mb-8 text-gray-800 leading-tight">Introduction to 7DT</h2>
                <p className="text-xl leading-relaxed text-gray-700">{mainText1}</p>
              </div>
              <div className="flex justify-center items-center h-full">
                <img 
                  src="./img/NGC0253.gif" 
                  alt="NGC0253 Galaxy" 
                  className="max-w-full max-h-full object-contain rounded-xl shadow-2xl"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Science Section - Right Aligned with Stats */}
        <div className="fullpage-section fullpage-content" style={{ 
          backgroundColor: "var(--primary-50)",
          backgroundImage: "linear-gradient(rgba(248, 250, 252, 0.1), rgba(248, 250, 252, 0.1)), url('./img/science.jpg')",
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundRepeat: "no-repeat"
        }}>
          <div className="container">
            <div className="flex justify-end">
              <div className="max-w-2xl text-right">
                <h2 className="text-4xl font-bold mb-6 text-gray-800" style={{ color: "white" }}>7 Scientific Goals</h2>
                <p className="text-lg leading-relaxed text-gray-700 mb-8" style={{ color: "white" }}>{mainText2}</p>
                <div className="science-stats">
                  <div className={`science-stat ${animateStats ? 'animate' : ''} ${statsAnimated ? 'animated' : ''}`}>
                    <span className="stat-number text-blue-600">7</span>
                    <div className="stat-label">Research Areas</div>
                  </div>
                  <div className={`science-stat ${animateStats ? 'animate' : ''} ${statsAnimated ? 'animated' : ''}`}>
                    <span className="stat-number text-purple-600">∞</span>
                    <div className="stat-label">Possibilities</div>
                  </div>
                  <div className={`science-stat ${animateStats ? 'animate' : ''} ${statsAnimated ? 'animated' : ''}`}>
                    <span className="stat-number text-green-600">100%</span>
                    <div className="stat-label">Innovation</div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Survey Section - Centered with Cards */}
        <div className="fullpage-section fullpage-content" style={{ 
          backgroundImage: "linear-gradient(rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0.2)), url('./img/survey.jpg')",
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundRepeat: "no-repeat"
        }}>
          <div className="container">
            <div className="text-center mb-12">
              <h2 className="text-4xl font-bold mb-6 text-gray-800" style={{ color: "white" }}>7 Dimensional Sky Survey</h2>
              <p className="text-lg leading-relaxed text-gray-700 max-w-3xl mx-auto" style={{ color: "white" }}>{mainText3}</p>
            </div>
                          <div className="max-w-4xl mx-auto text-center">
                <h3 className="text-lg font-semibold mb-4" style={{ color: "white" }}>Each dimension represents a fundamental aspect of astronomical observation</h3>
                <div className="seven-d-dimensions">
                  <span className={`dimension-item ${animateDimensions ? 'animate' : ''} ${dimensionsAnimated ? 'animated' : ''}`}>Latitude</span>
                  <span className={`dimension-item ${animateDimensions ? 'animate' : ''} ${dimensionsAnimated ? 'animated' : ''}`}>Longitude</span>
                  <span className={`dimension-item ${animateDimensions ? 'animate' : ''} ${dimensionsAnimated ? 'animated' : ''}`}>Distance</span>
                  <span className={`dimension-item ${animateDimensions ? 'animate' : ''} ${dimensionsAnimated ? 'animated' : ''}`}>Radial Velocity</span>
                  <span className={`dimension-item ${animateDimensions ? 'animate' : ''} ${dimensionsAnimated ? 'animated' : ''}`}>Brightness</span>
                  <span className={`dimension-item ${animateDimensions ? 'animate' : ''} ${dimensionsAnimated ? 'animated' : ''}`}>Wavelength</span>
                  <span className={`dimension-item ${animateDimensions ? 'animate' : ''} ${dimensionsAnimated ? 'animated' : ''}`}>Time</span>
                </div>
              </div>
          </div>
        </div>

        {/* Telescope Section - Split Layout */}
        <div className="fullpage-section fullpage-content" style={{ 
          backgroundColor: "var(--primary-50)",
          backgroundImage: "linear-gradient(rgba(248, 250, 252, 0.8), rgba(248, 250, 252, 0.8)), url('./img/telescope.jpg')",
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundRepeat: "no-repeat"
        }}>
          <div className="container">
            <div className="grid grid-cols-2 gap-12 items-center">
              <div>
                <h2 className="text-4xl font-bold mb-6 text-gray-800">7 Dimensional Telescope</h2>
                <p className="text-lg leading-relaxed text-gray-700">{mainText4}</p>
              </div>
              <div className="bg-white rounded-lg p-8 shadow-lg">
                <h3 className="text-2xl font-bold mb-4 text-gray-800">Key Features</h3>
                <ul className="space-y-3 text-gray-700">
                  <li className="flex items-center">
                    <span className="w-2 h-2 bg-blue-500 rounded-full mr-3"></span>
                    Multi-messenger observations
                  </li>
                  <li className="flex items-center">
                    <span className="w-2 h-2 bg-purple-500 rounded-full mr-3"></span>
                    Advanced imaging capabilities
                  </li>
                  <li className="flex items-center">
                    <span className="w-2 h-2 bg-green-500 rounded-full mr-3"></span>
                    Real-time data processing
                  </li>
                  <li className="flex items-center">
                    <span className="w-2 h-2 bg-orange-500 rounded-full mr-3"></span>
                    Automated observation scheduling
                  </li>
                </ul>
              </div>
            </div>
          </div>
        </div>

        {/* News Section */}
        <div className="fullpage-section fullpage-content" style={{ 
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundRepeat: "no-repeat"
        }}>
          <div className="container">
            <h2>Latest News</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {news.news.slice(0, 3).map((news, index) => (
                <div key={index} className="card">
                  <img src={`./img/news/${news.imgName}`} alt={news.title} className="w-full h-48 object-cover" />
                  <div className="card-info">
                    <div className="card-about">
                      <span className={`card-tag ${news.type === "meeting" ? "tag-news" : news.type === "publication" ? "tag-publication" : "tag-press"}`}>
                        {news.type}
                      </span>
                      <div className="text-sm text-gray-500">{news.date}</div>
                    </div>
                    <h3 className="card-title">{news.title}</h3>
                    {news.type === "meeting" ?
                      <div className="card-creator">in <a href="" className="text-primary-600 hover:text-primary-700">{news.place}</a></div> :
                      news.type === "publication" ?
                        <div className="card-creator">by <a href="" className="text-primary-600 hover:text-primary-700">{news.shortAuthor}</a></div> :
                        <div className="card-creator">by <a href="" className="text-primary-600 hover:text-primary-700">{news.source}</a></div>
                    }
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Footer Section - Inside fullpage wrapper but with special styling */}
        <div className="fullpage-section" style={{ 
          height: "auto",
          minHeight: "100vh",
          width: "100%",
          position: "relative",
          overflow: "visible",
          display: "block",
          scrollSnapAlign: "start"
        }}>
          <FooterBar />
        </div>
      </div>
    </div>
  );
}

export default MainPage;


